import (
	"context"
	"fmt"
	"testing"

	"github.com/redis/go-redis/v9"
	"github.com/redis/go-redis/v9/auth"
)

func TestDerivedClientsWithStreamingCredentials(t *testing.T) {
	ctx := context.Background()
	for _, warm := range []bool{false, true} {
		for _, kind := range []string{"Conn", "EphemeralConn", "Watch"} {
			t.Run(fmt.Sprintf("%s/warm=%t", kind, warm), func(t *testing.T) {
				updates := make(chan auth.Credentials)
				defer close(updates)
				p := &mockStreamingProvider{
					credentials: auth.NewBasicCredentials("default", "old-token"),
					updates:     updates,
				}
				c := redis.NewClient(&redis.Options{
					Addr: "127.0.0.1:16379", PoolSize: 1,
					StreamingCredentialsProvider: p,
				})
				defer c.Close()
				if warm {
					if err := c.Ping(ctx).Err(); err != nil {
						t.Fatal(err)
					}
				}
				defer func() {
					if r := recover(); r != nil {
						t.Errorf("derived client panicked: %v", r)
					}
				}()
				if kind == "Watch" {
					if err := c.Watch(ctx, func(tx *redis.Tx) error { return tx.Ping(ctx).Err() }, "repro-key"); err != nil {
						t.Fatal(err)
					}
					return
				}
				var cn *redis.Conn
				if kind == "Conn" {
					cn = c.Conn()
				} else {
					cn = c.EphemeralConn()
				}
				defer cn.Close()
				if err := cn.Ping(ctx).Err(); err != nil {
					t.Fatal(err)
				}
			})
		}
	}
}
